import React, { useState, useEffect } from 'react';
import Terminal from './components/Terminal';
import NestedArchitectureRenderer from './components/NestedArchitectureRenderer';
import WebSocketService from './services/WebSocketService';
import './App.css';

function App() {
  const [wsService, setWsService] = useState(null);
  const [architectureData, setArchitectureData] = useState({ deploymentUnits: [] });
  const [isConnected, setIsConnected] = useState(false);

  useEffect(() => {
    const webSocketService = new WebSocketService();
    
    webSocketService.onConnect = () => {
      console.log('Connected to WebSocket');
      setIsConnected(true);
    };

    webSocketService.onDisconnect = () => {
      console.log('Disconnected from WebSocket');
      setIsConnected(false);
    };

    webSocketService.onDiagramUpdate = (data) => {
      console.log('Architecture update received:', data);
      setArchitectureData({
        deploymentUnits: data.units || [],
        ...data
      });
    };

    webSocketService.connect();
    setWsService(webSocketService);

    return () => {
      if (webSocketService) {
        webSocketService.disconnect();
      }
    };
  }, []);

  return (
    <div className="App">
      <header className="App-header">
        <h1>APX CLI Banking Education Emulator</h1>
        <div className={`status ${isConnected ? 'connected' : 'disconnected'}`}>
          {isConnected ? '● Connected' : '● Disconnected'}
        </div>
      </header>
      
      <div className="App-content">
        <div className="terminal-panel">
          <Terminal wsService={wsService} isConnected={isConnected} />
        </div>
        
        <div className="diagram-panel">
          <NestedArchitectureRenderer architectureData={architectureData} />
        </div>
      </div>
    </div>
  );
}

export default App;
